from pathlib import Path
import json
from docx import Document
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.table import WD_TABLE_ALIGNMENT, WD_CELL_VERTICAL_ALIGNMENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'reports'/'Model_Development_Document.docx'
M=json.loads((ROOT/'reports'/'model_metrics.json').read_text(encoding='utf-8'))

def field(run,name):
    for tag,attrs,txt in [('w:fldChar',{'w:fldCharType':'begin'},None),('w:instrText',{'xml:space':'preserve'},name),('w:fldChar',{'w:fldCharType':'separate'},None),('w:t',{},'1'),('w:fldChar',{'w:fldCharType':'end'},None)]:
        e=OxmlElement(tag)
        for k,v in attrs.items(): e.set(qn(k),v)
        if txt: e.text=txt
        run._r.append(e)

def add_page(doc,title,paragraphs,table=None,*more):
    doc.add_page_break(); doc.add_heading(title,1)
    for text in paragraphs: doc.add_paragraph(text)
    if more: table=(table,more[0])
    if table:
        headers,rows=table; t=doc.add_table(rows=1,cols=len(headers)); t.style='Table Grid'; t.alignment=WD_TABLE_ALIGNMENT.CENTER
        for i,h in enumerate(headers):
            c=t.rows[0].cells[i]; c.text=h; c.vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
            sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'1F4E78'); c._tc.get_or_add_tcPr().append(sh)
            for r in c.paragraphs[0].runs: r.bold=True; r.font.color.rgb=RGBColor(255,255,255); r.font.size=Pt(8.5)
        t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
        for row in rows:
            cells=t.add_row().cells
            for i,value in enumerate(row):
                cells[i].text=str(value); cells[i].vertical_alignment=WD_CELL_VERTICAL_ALIGNMENT.CENTER
                for p in cells[i].paragraphs:
                    p.paragraph_format.space_after=Pt(1)
                    for r in p.runs: r.font.size=Pt(8.5)

# Use the supplied report template as the base; retain its one-section Letter geometry and Calibri identity.
doc=Document(ROOT/'reports'/'project_report_template_source.docx')
body=doc._element.body
for child in list(body):
    if child.tag!=qn('w:sectPr'): body.remove(child)
sec=doc.sections[0]; sec.page_width=Inches(8.5); sec.page_height=Inches(11)
sec.left_margin=Inches(1); sec.right_margin=Inches(1); sec.top_margin=Inches(.62); sec.bottom_margin=Inches(1)
sec.header_distance=Inches(.3); sec.footer_distance=Inches(.45)
normal=doc.styles['Normal']; normal.font.name='Calibri'; normal.font.size=Pt(10.5); normal.font.color.rgb=RGBColor(38,50,63)
normal.paragraph_format.space_after=Pt(6); normal.paragraph_format.line_spacing=1.08
for name,size,color in [('Title',27,'17365D'),('Subtitle',12,'54708F'),('Heading 1',16,'17365D')]:
    s=doc.styles[name]; s.font.name='Calibri'; s.font.size=Pt(size); s.font.color.rgb=RGBColor.from_string(color)
    s.font.bold=name!='Subtitle'
    if name=='Heading 1': s.paragraph_format.space_after=Pt(8); s.paragraph_format.keep_with_next=True

p=doc.add_paragraph(); p.paragraph_format.space_before=Pt(80); p.alignment=WD_ALIGN_PARAGRAPH.CENTER
r=p.add_run('MODEL DEVELOPMENT DOCUMENT'); r.bold=True; r.font.size=Pt(13); r.font.color.rgb=RGBColor(31,78,121)
p=doc.add_paragraph(style='Title'); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.add_run('House Price Prediction')
