p.add_run('Prepared 8 November 2026\n').bold=True; p.add_run('29,451 supplied listings · target price in lakhs · Streamlit application')
p=doc.add_paragraph(); p.alignment=WD_ALIGN_PARAGRAPH.CENTER; p.paragraph_format.space_before=Pt(115)
